#include "PatientSessionClock.h"
namespace dnxr { void PatientSessionClock::start(std::uint64_t now){ startMs_=now; state_={}; state_.realWorldTimeAnchorMs=now; } void PatientSessionClock::tick(std::uint64_t now,bool dec){ state_.sessionElapsedMs=now>=startMs_?now-startMs_:0; state_.virtualSceneElapsedMs=state_.sessionElapsedMs; state_.exposureTimeMs=state_.sessionElapsedMs; if(dec) state_.decompressionTimeMs+=1; } void PatientSessionClock::confirmPatient(std::uint64_t now){state_.lastPatientConfirmationMs=now;} void PatientSessionClock::confirmPhysician(std::uint64_t now){state_.lastPhysicianConfirmationMs=now;} PatientSessionClockState PatientSessionClock::state() const{return state_;} }
